#!/usr/bin/env bash
# Only publish EXPERIMENTAL packages generated by successful Kovelyx Windows CI.
set -euo pipefail

: "${GH_TOKEN:?A GitHub token is required}"
: "${GITHUB_REPOSITORY:?A repository is required}"
run_id="${BUILD_RUN_ID:-}"

if [[ -z "$run_id" ]]; then
  # Bootstrap: never fall back to an old successful build when a newer one
  # is still running or has failed.
  gh api "repos/$GITHUB_REPOSITORY/actions/workflows/windows.yml/runs?branch=main&per_page=10" > build-list.json
  run_id="$(jq -r '.workflow_runs[0].id // empty' build-list.json)"
  if [[ -z "$run_id" ]]; then
    echo "No Windows build yet. Waiting for a successful run."
    exit 0
  fi
fi

if [[ ! "$run_id" =~ ^[0-9]+$ ]]; then
  echo "::error::Invalid Windows run ID"
  exit 1
fi

gh api "repos/$GITHUB_REPOSITORY/actions/runs/$run_id" > build.json
if ! jq -e --arg repo "$GITHUB_REPOSITORY" '
  .head_repository.full_name == $repo and
  .head_branch == "main" and
  .name == "Kovelyx Windows - MSI et tests de packaging" and
  .status == "completed" and .conclusion == "success" and
  (.run_number | type == "number")
' build.json >/dev/null; then
  echo "Windows build $run_id not fully successful. No release published."
  exit 0
fi

source_sha="$(jq -r '.head_sha' build.json)"
# Must match the version EMBEDDED into the installer, not a synthetic GitHub run tag.
# The version helper reads source metadata from the exact commit that CI built.
release_version="$(python3 scripts/desktop-release-version.py --commit "$source_sha")"
tag="v$release_version"
git merge-base --is-ancestor "$source_sha" HEAD || {
  echo "::error::Source commit is not in main history"
  exit 1
}

gh api "repos/$GITHUB_REPOSITORY/actions/runs/$run_id/jobs?per_page=100" > jobs.json
jq -e '[.jobs[] | select(.name=="Compiler Kovelyx Windows" and .conclusion=="success")] | length == 1' jobs.json >/dev/null || {
  echo "::error::Windows packaging and tests have not succeeded"
  exit 1
}

gh api "repos/$GITHUB_REPOSITORY/actions/runs/$run_id/artifacts?per_page=100" > artifacts.json
jq -e '[.artifacts[] | select(.name=="Kovelyx-Windows-installers-experimental" and .expired==false)] | length == 1' artifacts.json >/dev/null || {
  echo "::error::Windows installer artifact is unavailable, expired, or ambiguous"
  exit 1
}

mkdir -p input dist
gh run download "$run_id" --repo "$GITHUB_REPOSITORY" \
  --name Kovelyx-Windows-installers-experimental --dir input

mapfile -d '' -t setups < <(find input -type f -name 'Kovelyx-Windows-Setup-*.exe' -print0)
mapfile -d '' -t msis < <(find input -type f -name 'Kovelyx-Windows-*.msi' -print0)
mapfile -d '' -t portables < <(find input -type f -name 'Kovelyx-Windows-Portable-*.zip' -print0)
if (( ${#setups[@]} != 1 || ${#msis[@]} != 1 || ${#portables[@]} != 1 )); then
  echo "::error::A unique setup EXE, MSI, and complete portable ZIP are required"
  exit 1
fi

for path in "${setups[0]}" "${msis[0]}" "${portables[0]}"; do
  if [[ ! -s "$path.sha256" || "$(stat -c %s "$path")" -lt 1000000 ]]; then
    echo "::error::Missing checksum or invalid package size"
    exit 1
  fi
  (cd "$(dirname "$path")" && sha256sum --check -- "$(basename "$path").sha256")
done

if [[ "$(od -An -tx1 -N2 "${setups[0]}" | tr -d '[:space:]')" != "4d5a" ]]; then
  echo "::error::Setup.exe does not have a Windows executable header"
  exit 1
fi
unzip -Z -1 "${portables[0]}" > portable-entries.txt
if ! grep -Eq '(^|/)Kovelyx[.]exe$' portable-entries.txt; then
  echo "::error::Portable archive does not contain Kovelyx.exe"
  exit 1
fi

cp -- "${setups[0]}" "dist/Kovelyx-Windows-Setup-$tag.exe"
cp -- "${msis[0]}" "dist/Kovelyx-Windows-$tag.msi"
cp -- "${portables[0]}" "dist/Kovelyx-Windows-Portable-$tag.zip"
(cd dist && for file in ./*.exe ./*.msi ./*.zip; do sha256sum -- "$file" > "$file.sha256"; done)

cat > release-notes.md <<EOF
## Kovelyx Windows — preview $tag

**Recommended download:** Kovelyx-Windows-Setup-$tag.exe (one file to INSTALL).
The MSI is an alternative installer. The portable ZIP must retain the complete app and Java runtime folders.

- Source Windows CI: https://github.com/$GITHUB_REPOSITORY/actions/runs/$run_id
- Source commit: $source_sha
- SHA-256 checksums are provided for every file.
- This build is **experimental, unsigned and not certified on real hardware**.
- Playback, extensions, tracking sign-in, and updates still need real-PC verification.
- License and dependency notices: https://github.com/$GITHUB_REPOSITORY/blob/main/docs/PROVENANCE.md

This is NOT a stable release. Do not ignore Windows security warnings.
EOF

if gh release view "$tag" --repo "$GITHUB_REPOSITORY" >/dev/null 2>&1; then
  gh release view "$tag" --repo "$GITHUB_REPOSITORY" --json isPrerelease --jq '.isPrerelease' | grep -qx true || {
    echo "::error::Refusing to alter an existing stable release"
    exit 1
  }
  gh release upload "$tag" --repo "$GITHUB_REPOSITORY" --clobber \
    dist/*.exe dist/*.exe.sha256 dist/*.msi dist/*.msi.sha256 dist/*.zip dist/*.zip.sha256
else
  gh release create "$tag" --repo "$GITHUB_REPOSITORY" \
    --target "$source_sha" --title "Kovelyx Windows $tag — test" \
    --prerelease --notes-file release-notes.md \
    dist/*.exe dist/*.exe.sha256 dist/*.msi dist/*.msi.sha256 dist/*.zip dist/*.zip.sha256
fi

echo "Published Windows preview: $tag"
{
  echo "### Windows preview $tag"
  echo "Compiled by https://github.com/$GITHUB_REPOSITORY/actions/runs/$run_id"
  echo "Release: https://github.com/$GITHUB_REPOSITORY/releases/tag/$tag"
} >> "$GITHUB_STEP_SUMMARY"
